 for key in ['initial_to_best_model_edge_normalized_improvement','initial_to_best_including_derived_edge_normalized_improvement','initial_to_last_batch_edge_normalized_improvement','derived_beyond_best_model_edge_normalized_improvement']:
  values=[r[key]for r in rows if r[key]is not None];s[key]=dict(valid_pairs=len(values),positive=sum(v>0 for v in values),zero=sum(v==0 for v in values),negative=sum(v<0 for v in values),mean=statistics.mean(values)if values else None,median=statistics.median(values)if values else None)
 summaries.append(s)
